mapper.select:
SELECT  FROM MARKETING_TOUCH_TASK t
 WHERE 1=1
 ORDER BY t.created_time DESC LIMIT #{offset},#{limit}

SELECT  FROM MARKETING_TOUCH_TASK t
 WHERE 1=1

  AND t.org_id = #{viewerOrgId}
  AND (
      t.assignee_emp_id = #{viewerEmpId}
      OR EXISTS (
          SELECT 1
            FROM MARKETING_TOUCH_WORKLOG wv
            JOIN MARKETING_TOUCH_WORKLOG_PARTICIPANT pv ON pv.worklog_id = wv.id
           WHERE wv.task_id = t.id
             AND wv.record_status = 'VALID'
             AND wv.operator_emp_id = t.assignee_emp_id
             AND pv.participant_emp_id = #{viewerEmpId}
             AND pv.participant_role = 'COLLABORATOR'
             AND pv.participant_org_id = t.org_id
      )
  )
ORDER BY t.created_time DESC LIMIT #{offset},#{limit}

SELECT COUNT(*) FROM MARKETING_TOUCH_TASK t WHERE 1=1

  AND t.org_id = #{viewerOrgId}
  AND (
      t.assignee_emp_id = #{viewerEmpId}
      OR EXISTS (
          SELECT 1
            FROM MARKETING_TOUCH_WORKLOG wv
            JOIN MARKETING_TOUCH_WORKLOG_PARTICIPANT pv ON pv.worklog_id = wv.id
           WHERE wv.task_id = t.id
             AND wv.record_status = 'VALID'
             AND wv.operator_emp_id = t.assignee_emp_id
             AND pv.participant_emp_id = #{viewerEmpId}
             AND pv.participant_role = 'COLLABORATOR'
             AND pv.participant_org_id = t.org_id
      )
  )

SELECT  FROM MARKETING_TOUCH_TASK
WHERE cust_id=#{custId} AND assignee_emp_id=#{assigneeEmpId}
  AND task_status IN ('PENDING','IN_PROGRESS') ORDER BY created_time DESC

SELECT COUNT(*) FROM MARKETING_TOUCH_TASK WHERE org_id=#{orgCode}
  AND created_time >= CONCAT(#{startDate},' 00:00:00')
  AND created_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
  AND task_status=#{status}

SELECT  FROM MARKETING_TOUCH_TASK t
 WHERE 1=1

AND t.org_id=#{orgId}
ORDER BY t.created_time DESC LIMIT #{offset},#{limit}
